 (R/'exclusion_audit.json').write_text(json.dumps(dict(passed=True,new_sequences=len(targets),exclusions=checks),indent=2));print('Fresh bank',len(b['rows']),'contexts',[(t['split'],t['id']) for t in b['topics']])
